@st.composite
def gen(draw):
    N = draw(st.integers(1, 3))
    p = draw(st.sampled_from([2, 3, 5, 7]))
    A = [[draw(st.integers(0, p - 1)) for _ in range(N)] for _ in range(N)]
    # Limit the number of zeros so that (p-1)^K stays small.
    zeros = [(i, j) for i in range(N) for j in range(N) if A[i][j] == 0]
    while len(zeros) > 4:
        i, j = zeros.pop()
        A[i][j] = draw(st.integers(1, p - 1))
    lines = [f"{N} {p}"]
    for i in range(N):
        lines.append(" ".join(str(x) for x in A[i]))
    return "\n".join(lines) + "\n"


