def _matpow_literal(B, e, p):
    # B^e computed literally as e successive multiplications, mod p
    n = len(B)
    R = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    for _ in range(e):
        R = _matmul(R, B, p)
    return R


